function pageHtml(){return `<div class="eai-hero"><h2>EA &amp; Indicator</h2><div class="eai-sub">Professional PipSePaisa MT4/MT5 tools with private account-licensed delivery. Browse the product, review how it works, then request your own licensed build.</div><div class="eai-toolbar"><div class="eai-tabs" id="eaiTypeTabs"><button class="eai-chip on" data-v="all">All</button><button class="eai-chip" data-v="indicator">Indicators</button><button class="eai-chip" data-v="ea">EAs</button></div><div class="eai-tabs" id="eaiAccessTabs"><button class="eai-chip on" data-v="all">All</button><button class="eai-chip" data-v="free">Free</button><button class="eai-chip" data-v="paid">Paid</button></div></div></div><div id="eaiMyRequests"></div><div class="eai-grid" id="eaiProductGrid"><div class="card" style="padding:28px;text-align:center">Loading EA &amp; Indicator…</div></div>`}
function ensureEaNav(){
 const menu=document.querySelector('#sidebar .menu');if(!menu)return null;
 const matches=[...menu.querySelectorAll('[data-page="eaindicator"]')];
 let item=matches[0]||null;
 if(!item){item=document.createElement('div');item.className='menu-item';item.dataset.page='eaindicator';item.innerHTML='<span class="menu-icon">🧩</span><strong>EA &amp; Indicator</strong>';}
 matches.slice(1).forEach(x=>x.remove());
 item.style.order='7';
 item.onclick=function(){window.showPage?.('eaindicator',item);const pt=document.getElementById('pageTitle');if(pt)pt.textContent='EA & Indicator';load()};
 const signals=menu.querySelector('[data-page="signals"]');
 if(signals&&signals.nextElementSibling!==item)signals.insertAdjacentElement('afterend',item);
 return item;
}
function installPage(){addCss();let page=document.getElementById('page-eaindicator');if(!page){page=document.createElement('div');page.className='page';page.id='page-eaindicator';page.innerHTML=pageHtml();document.querySelector('.main-content,.content')?.appendChild(page)}
 ensureEaNav();
 document.querySelectorAll('#eaiTypeTabs .eai-chip').forEach(b=>b.onclick=()=>{state.type=b.dataset.v;document.querySelectorAll('#eaiTypeTabs .eai-chip').forEach(x=>x.classList.toggle('on',x===b));renderProducts()});
 document.querySelectorAll('#eaiAccessTabs .eai-chip').forEach(b=>b.onclick=()=>{state.access=b.dataset.v;document.querySelectorAll('#eaiAccessTabs .eai-chip').forEach(x=>x.classList.toggle('on',x===b));renderProducts()});
}
function productCard(p){
 const minDeposit=Math.max(0,Number(p.requirements?.min_deposit_usd)||0);
 const license=state.requests.find(r=>r.product_id===p.id&&['ready','downloaded'].includes(r.status)&&r.license_expires_at);
 const expiry=license?.license_expires_at||'';
 const expired=license&&Date.parse(expiry)<=Date.now();
 const licenseTimer=license?`<div class="eai-card-license-clock ${expired?'expired':''}" aria-label="License time remaining"><span>${expired?'LICENSE EXPIRED':'LICENSE REMAINING'}</span><strong data-eai-license-expiry="${esc(expiry)}">${esc(licenseRemaining(expiry))}</strong></div>`:'';
 return `<article class="eai-card" onclick="PSPEAIndicator.detail('${p.id}')"><div class="eai-cover">${p.cover_url?`<img loading="lazy" decoding="async" src="${esc(p.cover_url)}" alt="${esc(p.title)}">`:`<span>${p.product_type==='ea'?'🤖':'📊'}</span>`}</div><div class="eai-body"><div class="eai-kicker"><span>${p.product_type==='ea'?'EA':'Indicator'} · ${esc(p.platform)}</span><span>${/^v/i.test(String(p.version||''))?'':'v'}${esc(p.version||'1.0')}</span></div><div class="eai-title">${esc(p.title)}</div><div class="eai-desc">${esc(p.short_description||'Professional PipSePaisa trading tool.')}</div><div class="eai-meta"><span class="eai-tag ${p.access_type==='free'?'free':''}">${p.access_type==='free'?'FREE':esc(p.currency||'USD')+' '+Number(p.price||0).toFixed(0)}</span>${minDeposit?`<span class="eai-tag">Min ${esc(minDeposit)} broker deposit</span>`:''}<span class="eai-tag">Account Licensed</span><span class="eai-tag">View Details</span></div>${licenseTimer}</div></article>`;
}
function renderProducts(){const g=document.getElementById('eaiProductGrid');if(!g)return;const rows=state.products.filter(p=>(state.type==='all'||p.product_type===state.type)&&(state.access==='all'||p.access_type===state.access));g.innerHTML=rows.length?rows.map(productCard).join(''):'<div class="card" style="grid-column:1/-1;padding:30px;text-align:center;color:var(--text-muted)">No products in this filter yet.</div>'}
function setupLive(c,userId){
if(P.liveUser===userId||!c.channel)return;
if(P.liveChannel)try{c.removeChannel(P.liveChannel)}catch(e){}
P.liveUser=userId;
try{P.liveChannel=c.channel('psp-eai-user-license-'+userId).on('postgres_changes',{event:'UPDATE',schema:'public',table:'ea_indicator_requests',filter:'user_id=eq.'+userId},function(payload){
var row=payload.new||{},old=P.requests.find(function(x){return x.id===row.id});
if(!old)return;
if(row.status===old.status)return;
if(row.status!=='downloaded')toast('Indicator application updated: '+label(row.status));
api.load();
}).subscribe()}catch(e){P.liveUser=null;console.warn('EA license live updates unavailable',e)}
}
